CREATE OR REPLACE FUNCTION public.spend_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,private AS $$ SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_active AND deleted_at IS NULL) THEN NULL WHEN public.is_erp_admin(auth.uid()) THEN 'finance' WHEN private.has_app_access(auth.uid(),'spend') THEN CASE WHEN public.can_manage_cash_flow(auth.uid()) THEN 'finance' ELSE 'holder' END END $$; REVOKE ALL ON FUNCTION public.spend_role() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.spend_role() TO authenticated;